<template><section class="max-w-xl space-y-5"><h1 class="text-2xl font-semibold">Change password</h1><form class="space-y-4 rounded-xl bg-background p-6 shadow" @submit.prevent="submit"><input v-model="currentPassword" type="password" required placeholder="Current password" class="w-full rounded border p-3" /><input v-model="newPassword" type="password" minlength="8" required placeholder="New password" class="w-full rounded border p-3" /><button class="rounded bg-primary px-5 py-3 text-primary-foreground">Update password</button><p>{{ message }}</p></form></section></template>
<script setup lang="ts">import { ref } from "vue"; import { authHttp } from "@/auth"; const currentPassword = ref(""); const newPassword = ref(""); const message = ref(""); const submit = async () => { try { await authHttp.post("/api/auth/password", { currentPassword: currentPassword.value, newPassword: newPassword.value }); message.value = "Password updated."; } catch { message.value = "Unable to update password."; } };</script>
